import{_ as t,o as s,c as i,a5 as n}from"./chunks/framework.BvXk9IVy.js";const g=JSON.parse('{"title":"中文排版里的几个小决定","description":"","frontmatter":{"title":"中文排版里的几个小决定"},"headers":[],"relativePath":"notes/chinese-typography.md","filePath":"notes/chinese-typography.md","lastUpdated":1791895356000}'),o={name:"notes/chinese-typography.md"};function a(p,e,d,l,c,r){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="中文排版里的几个小决定" tabindex="-1">中文排版里的几个小决定</h1><blockquote><p>排版是读者看不见的那部分设计，看不见，但它一直在起作用。</p></blockquote><h2 id="行高-1-9" tabindex="-1">行高 1.9</h2><p>默认主题的行高是按西文正文调的。英文有小写字母和升降部，行与行之间自带一层空气；中文是方块字，字面几乎撑满整个字身框，同样行距下会明显更挤。</p><p>这间书斋里，凡是成段的中文都放到了 <code>line-height: 1.9</code>——首页横幅下面那句简介就是这一档。卡片里的短评、歌词这些窄栏文字，用 1.75 到 1.85。原则只有一条：<strong>一行越长，行高就得越大</strong>。宽屏上的长段落，1.9 才刚够让眼睛在换行时找得回位置。</p><h2 id="字距-0-02em-到-0-06em" tabindex="-1">字距 0.02em 到 0.06em</h2><p>字距是比行高更细的一档。没有它，中文看起来会有点「糊」——尤其标题。</p><p>实际用下来分三层：</p><ul><li><strong>0.02em</strong>：卡片描述、图注这类小字，只求不挤。</li><li><strong>0.03em 到 0.04em</strong>：正文与标题的主力档位。</li><li><strong>0.06em 及以上</strong>：只给短句。比如首页那一句格言，用到 0.06em；再往上，比如印章里那个字，可以到 0.14em。</li></ul><p>字距不能滥用。整段文字拉开太多，读起来会像被人一个字一个字往外蹦。</p><h2 id="标点挤压" tabindex="-1">标点挤压</h2><p>中文排版里最麻烦的其实不是字体，是标点。</p><p>全角逗号和句号后面天生带着一块空白，用在行尾时那块空白会戳出边界，看起来像没对齐。严格的做法是按标点的位置分别裁掉左半边或右半边，叫作标点挤压。CSS 里没有能直接打开这个行为的开关——能靠 <code>text-spacing</code> 或者半角标点模拟，但换行位置一乱就会出更多问题。我在这个项目里的做法是折中：顿号、引号、书名号一律用全角，需要收紧的地方靠字号和行高去补，不去做自动挤压。</p><p>不完美，但稳定。对我这种一个人维护的站来说，稳定比完美重要。</p><h2 id="为什么是霞鹜文楷" tabindex="-1">为什么是霞鹜文楷</h2><p>挑字体绕不开三个条件：看着安静、开源可商用、有中文的字量。</p><p>霞鹜文楷的骨架来自手写楷体，但笔画收得干净，没有毛笔的飞白。它不像宋体那样正式，也不像黑体那样硬。放在这里正合适——像一本翻旧了的书，而不是一份打印出来的材料。</p><h2 id="只引两个字族的真正原因" tabindex="-1">只引两个字族的真正原因</h2><p>字体放在 1.x 版本的 <code>lxgw-wenkai-webfont</code> 包里。这个包的 <code>style.css</code> 一次会带进 <strong>6 个字族</strong>——正文和等宽的 regular / light / bold，一共 <strong>582 个切片文件，约 31MB</strong>。</p><p>但对这个站来说，其中大部分永远不会被命中：</p><ul><li><code>--vp-font-family-base</code> 只声明了 <code>&#39;LXGW WenKai&#39;</code>，等宽那三个字族根本用不上；</li><li>light(300) 没有任何样式在用；</li><li>卡片标题的字重是 600，归到 bold(700) 那一档就够了。</li></ul><p>所以在 <code>theme/index.ts</code> 里，我只引两个入口：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes rose-pine-dawn rose-pine-moon vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#286983;--shiki-dark:#3E8FB0;">import </span><span style="--shiki-light:#EA9D34;--shiki-dark:#F6C177;">&#39;lxgw-wenkai-webfont/lxgwwenkai-regular.css&#39;</span></span>
<span class="line"><span style="--shiki-light:#286983;--shiki-dark:#3E8FB0;">import </span><span style="--shiki-light:#EA9D34;--shiki-dark:#F6C177;">&#39;lxgw-wenkai-webfont/lxgwwenkai-bold.css&#39;</span></span></code></pre></div><p>少打包 388 个用不上的文件。<strong>这不会影响显示</strong>，因为每个 <code>@font-face</code> 都带着 <code>unicode-range</code>——浏览器只会去下载页面里真正出现过的那几个切片，其余的一律不请求。所谓「按需」在这里是双向的：打包时按需，加载时也按需。</p><h2 id="小结" tabindex="-1">小结</h2><p>行高、字距、标点、字体，四件事没有一件是「对」或「错」，只有合不合适。判断标准也很朴素：读完整段之后，眼睛累不累。</p>`,26)])])}const m=t(o,[["render",a]]);export{g as __pageData,m as default};
